#include <CoreFoundation/CoreFoundation.h>
#include <IOKit/IOKitLib.h>
#include <stdio.h>
int main(void){io_iterator_t it=0; if(IOServiceGetMatchingServices(kIOMainPortDefault,IOServiceMatching("IOUSBHostDevice"),&it))return 2;io_service_t dev;while((dev=IOIteratorNext(it))){CFMutableDictionaryRef props=0;if(!IORegistryEntryCreateCFProperties(dev,&props,kCFAllocatorDefault,0)){CFNumberRef v=CFDictionaryGetValue(props,CFSTR("idVendor"));CFNumberRef p=CFDictionaryGetValue(props,CFSTR("idProduct"));int vid=0,pid=0;if(v)CFNumberGetValue(v,kCFNumberIntType,&vid);if(p)CFNumberGetValue(p,kCFNumberIntType,&pid);if(vid==0x0bda&&pid==0x8922){printf("REALTEK=%04x:%04x\n",vid,pid);const char* keys[]={"idVendor","idProduct","bDeviceClass","locationID"};for(int i=0;i<4;i++){CFStringRef key=CFStringCreateWithCString(0,keys[i],kCFStringEncodingUTF8);CFTypeRef val=CFDictionaryGetValue(props,key);int n=0;Boolean ok=val&&CFGetTypeID(val)==CFNumberGetTypeID()&&CFNumberGetValue((CFNumberRef)val,kCFNumberIntType,&n);printf("%s present=%d number=%d conversion=%d value=%d\n",keys[i],!!val,val&&CFGetTypeID(val)==CFNumberGetTypeID(),ok,n);CFRelease(key);}const char* names[]={"USB Vendor Name","USB Product Name"};for(int i=0;i<2;i++){CFStringRef key=CFStringCreateWithCString(0,names[i],kCFStringEncodingUTF8);CFStringRef v=CFDictionaryGetValue(props,key);char buffer[128]={0};Boolean ok=v&&CFGetTypeID(v)==CFStringGetTypeID()&&CFStringGetCString(v,buffer,sizeof(buffer),kCFStringEncodingUTF8);printf("%s present=%d string=%d value=%s\n",names[i],!!v,ok,buffer);CFRelease(key);}}CFRelease(props);}IOObjectRelease(dev);}IOObjectRelease(it);return 0;}
